package vn.contractgovernance.api.files;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import vn.contractgovernance.api.shared.*;
import java.time.Clock;
import java.sql.Timestamp;
import java.util.UUID;
/** Files-owned registration of scanned generated bytes; caller retains PendingWrite until commit.
 * This original renderer contains necessary synthetic business facts and evidence references,
 * never IDENTITY_IMAGE bytes. It follows the canonical original SERVICE_TERMS classification;
 * parent authorization and independent auditor full-download restrictions still apply.
 */
@Service
public class GeneratedArtifactFiles {
 private final EntityStore store;private final JsonSupport json;private final Clock clock;private final AuditService audit;private final ContractRegistry schemas;
 public GeneratedArtifactFiles(EntityStore store,JsonSupport json,Clock clock,AuditService audit,ContractRegistry schemas){this.store=store;this.json=json;this.clock=clock;this.audit=audit;this.schemas=schemas;}
 @Transactional(propagation=Propagation.MANDATORY)
 public EntityStore.Entity register(EntityStore.Entity contract,PrivateBlobStore.Stored blob,ClamAvScanner.Result scan,String renderer,String generatedAt){
  if(scan.infected()||!blob.mediaType().equals("application/pdf"))throw ApiException.of("STORAGE_INTEGRITY","Bản sinh không phải PDF an toàn.");
  String kind=switch(contract.type()){case "Change"->"CHANGE";case "Contract"->"CONTRACT";case "Notice"->"NOTICE";default->throw ApiException.of("STORAGE_INTEGRITY","Nguồn artifact không được hỗ trợ.");};
  var id=UUID.randomUUID();var now=JsonSupport.timestamp(clock.instant());var b=json.object().put("createdAt",now).put("updatedAt",now).put("branchId",contract.branchId().toString()).put("state","CLEAN").put("targetKind",kind).put("targetId",contract.id().toString()).put("purpose",kind.equals("NOTICE")?"NOTICE_EVIDENCE":"SERVICE_TERMS").put("mediaType","application/pdf").put("filename",(kind.equals("CHANGE")?"phu-luc-":"hop-dong-")+contract.id()+".pdf").put("sizeBytes",blob.sizeBytes()).put("sha256",blob.sha256()).put("scannerVersion",scan.engineVersion()).put("signatureDatabaseVersion",scan.databaseVersion()).put("scannedAt",now).put("humanVerification","NOT_CHECKED").put("sensitive",false).put("attached",true).put("origin","GENERATED").put("rendererVersion",renderer).put("generatedAt",generatedAt);b.putNull("scanJobId");b.putNull("uploadedBy");b.set("allowedActions",json.array());b.set("blockedActions",json.array());var file=store.create("File",id,contract.branchId(),b);schemas.validateSchema("File",file.body());
  store.jdbc().update("insert into cg_file_blob(file_id,storage_key,original_sha256,size_bytes,created_at) values(?,?,?,?,?)",id,blob.key(),blob.sha256(),blob.sizeBytes(),Timestamp.from(clock.instant()));store.jdbc().update("insert into cg_file_association(file_id,target_type,target_id,historical,created_at) values(?,?,?,true,?)",id,kind,contract.id(),Timestamp.from(clock.instant()));audit.record(null,"CREATE",file,null);return file;
 }
}
